import sys
sys.path.insert(0,'/opt/tools')
import casa_tool, numpy as np
s=casa_tool.Session(); st=s.state()
for n,b in st['bodies'].items(): print(n, np.round(b['pos'],3))
print('sites')
for i in range(s.model.nsite):
 n=s.model.site(i).name
 if 'grip' in n or 'obj' in n or 'container' in n: print(n,np.round(s.data.site_xpos[i],3))
print('geoms')
for i in range(s.model.ngeom):
 n=s.model.geom(i).name
 if any(k in n for k in ['obj','container']): print(n,np.round(s.data.geom_xpos[i],3))
